create database moviesdb
use moviesdb

create table movies (
    movie_id int primary key,
    movie_title varchar(150),
    director_id int,
    genre_id int,
    release_year int,
    language varchar(50),
    duration_minutes int,
    production_budget decimal(15,2),
    box_office_collection decimal(15,2),
    rating decimal(3,1),
    certificate varchar(10),
    country varchar(50),
    streaming_platform varchar(100),
    award_count int,
    movie_status varchar(30)
);


TASKS 

1:Display all movies. 
select * from movies

2:Find movies released after a specified year. 
select * from movies
where release_year > 2020;

3:Sort movies by rating
select movie_id, movie_title, rating, release_year
from movies
order by rating desc;

4:Group movies by genre.
select genre_id,count(*) as TotalMovies
from movies
group by genre_id;


5:Calculate average ratings by genre.
select genre_id, avg(rating) as averagerating from movies
group by genre_id
order by averagerating desc;

6:Display the top 10 movies by box office collection
select top 10  movie_id,movie_title,release_year,box_office_collection
from movies
order by box_office_collection desc;

7:Create directors and genres tables and join them with movies.
create table Directors
(
    director_id INT PRIMARY KEY,
    director_name VARCHAR(100)
);


select * from Directors


create table Genres1
(
    genre_id INT PRIMARY KEY,
    genre_name VARCHAR(50)
);


select * from Genres1

select
    m.movie_id,
    m.movie_title,
    d.director_name,
    g.genre_name,
    m.release_year,
    m.language,
    m.rating,
    m.box_office_collection
from movies m
inner join Directors d
on M.director_id = D.director_id
inner join Genres1 g
on M.genre_id = G.genre_id;

8:Find genres with more than 20 movies. 
select genre_id,
    count(*) as totalmovies
from movies
group by genre_id
having count(*) > 20;

9:Calculate total box office collection by release year. 
select release_year,
sum(box_office_collection) as TotalCollection
from movies
group by release_year
order by TotalCollection desc;


 